const data = items[0].json;

// Extract date key (ignore traceId)
const dateKey = Object.keys(data).find(
  key => /^\d{4}-\d{2}-\d{2}$/.test(key)
);
console.log(items,dateKey);
if (!dateKey) {
  return [{
    json: {
      availability: "No available time slots were found."
    }
  }];
}

const slots = data[dateKey]?.slots || [];

if (!slots.length) {
  return [{
    json: {
      availability: `No available time slots on ${dateKey}.`
    }
  }];
}

// Format times correctly
const formattedSlots = slots.map(slot =>
  new Date(slot).toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    hour12: true,
    timeZone: "America/New_York"
  })
);

// Limit to first 6 slots (Retell-safe)
const limited = formattedSlots.join(", ");

return [{
  json: {
    date: dateKey,
    slots,
    availability: `Available times on ${dateKey} are ${limited} Eastern Time.`
  }
}];

const requested = new Date(
  $('Retell Webhook').item.json.body.args.startDate
);

// Start of requested day (calendar timezone)
const startDate = new Date(requested);
startDate.setHours(0, 0, 0, 0);

// End of requested day (exclusive)
const endDate = new Date(startDate.getTime() + 24 * 60 * 60 * 1000);

return {
  startDate: startDate.getTime(),
  endDate: endDate.getTime(),
  timezone: "America/New_York",
  calendarId: "{{CALENDAR_ID}}"
};

const spokenTime = $('Retell Webhook').item.json.body.args.startTime;
const freeSlotsResponse = $('GHL Get Free Slots').item.json;

// Validate response
if (!Array.isArray(freeSlotsResponse) || !freeSlotsResponse.length) {
  return [{
    json: {
      error: 'No free slots available'
    }
  }];
}

const data = freeSlotsResponse[0];
const date = Object.keys(data).find(k => /^\d{4}-\d{2}-\d{2}$/.test(k));

if (!date) {
  return [{
    json: {
      error: 'No valid date found'
    }
  }];
}

const slots = data[date].slots;

// Match spoken time with free slot
const matchedSlot = slots.find(s =>
  new Date(s).toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZone: 'America/New_York'
  }) === spokenTime
);

if (!matchedSlot) {
  return [{
    json: {
      error: 'Selected time is no longer available'
    }
  }];
}

// Success — return matched slot
return [{
  json: {
    startTime: matchedSlot
  }
}];

